var t=[{title:`Fă un buget de timp`,text:`Timpul total al unui antrenament include pregătirea, încălzirea, aranjarea fiecărui exercițiu, seriile de lucru, pauzele, trecerile de la un exercițiu la altul și o eventuală revenire. Într-o sesiune de forță, timpul în care chiar ridici este adesea doar o mică parte din total. Trei serii de câte 40 de secunde, cu două minute de pauză între ele, durează în jur de șase minute pentru acel exercițiu, fără schimbările de echipament.`},{title:`O estimare simplă`,text:`Adună timpul de încălzire, durata fiecărei serii de lucru, pauzele dintre serii și schimbările de echipament. De exemplu, patru exerciții × trei serii de câte 40 de secunde înseamnă opt minute de lucru efectiv. Dacă fiecare exercițiu are două pauze de 90 de secunde, adaugă douăsprezece minute. O încălzire de șase minute și circa opt minute de pregătire și schimbări aduc sesiunea la aproximativ 34 de minute. Pauzele mai lungi la efortul greu pot schimba mult totalul.`},{title:`Varianta de 20 de minute`,text:`Păstrează încălzirea scurtă, alege două sau trei tipare principale de mișcare și fă câteva serii bune din fiecare. Împerecherea unei împingeri cu o tragere poate economisi timp la schimbări, când echipamentul și tehnica ți-o permit, dar nu reduce pauzele atât de mult încât să pierzi obiectivul principal de forță.`},{title:`Variante de 30–45 de minute`,text:`Adaugă o mișcare de tip balansare din șold sau fandare, un exercițiu pentru trunchi sau serii în plus pentru tiparul tău prioritar. Dacă obiectivul tău este condiția fizică generală, folosește timpul rămas pentru efort aerob. Nu trebuie să umpli fiecare minut liber cu „finisări”.`},{title:`Protejează-ți prioritățile`,text:`Când timpul e scurt, renunță mai întâi la exercițiile auxiliare cu prioritate mică. Păstrează încălzirea și nu te grăbi la ridicările compuse grele. Dacă tot programul depășește mereu timpul, planifică mai puțin pentru fiecare sesiune, în loc să te bazezi pe un ritm pe care nu îl poți menține.`},{title:`Folosirea TrainUp`,text:`Setează în Profil durata sesiunii la minutele pe care le ai cu adevărat. Dacă termini munca principală cu tehnică bună, sesiunea a fost un succes, chiar dacă ai sărit peste extrele opționale.`}];var a=[{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`CDC: planificarea practică a activității fizice`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`}];var r={sections:t,sources:a};export{r as default,t as sections,a as sources};